-- Bridge <-> Lua contract: tests/fixtures/bridge_contract.json is generated by the Python
-- bridge's own map_now_playing() (bridge/tests/test_contract_fixture.py keeps it in sync).
-- Every field must survive np.providers.bridge unchanged (or with the documented default).
local T = ...
local FakeDeps = require("fake_deps")
local Bridge = require("np.providers.bridge")
local Config = require("c4.config")
local json = require("np.json")
local pbm = require("np.playback")

local docs = json.decode(T.fixture("bridge_contract.json"))

local function poll(doc, cfg)
  local fd = FakeDeps.new()
  fd:route("/now-playing", { status = 200, body = json.encode(doc) })
  local p = Bridge.new(cfg or { url = "http://192.168.1.10:8765/v1/devices/Den/now-playing", provider_name = "appletv" }, fd.deps)
  local r = {}
  p:poll(function(err, pb) r.err, r.pb = err, pb end)
  fd:flush()
  return r.err, r.pb, fd
end

describe("bridge contract (Python map_now_playing -> np.providers.bridge)", function()
  for _, name in ipairs({ "movie", "episode", "music", "live", "idle", "off" }) do
    it(name .. ": every field maps 1:1", function()
      local doc = docs[name]
      T.ok(doc, "fixture has " .. name)
      local err, pb, fd = poll(doc)
      T.is_nil(err)
      for _, f in ipairs(pbm.SOURCE_FIELDS) do T.eq(pb.source[f], doc.source[f], "source." .. f) end
      local p, dp = pb.playback, doc.playback
      T.eq(p.state, dp.state, "playback.state")
      T.eq(p.position_s, dp.position_s, "position_s")
      T.eq(p.duration_s, dp.duration_s, "duration_s")
      T.eq(p.volume, dp.volume, "volume (bridge sends 0..100, Lua keeps 0..100)")
      T.eq(p.is_live, dp.is_live == true, "is_live (null -> false)")
      T.eq(p.position_updated_at, dp.position_updated_at or fd.t, "position_updated_at (null -> now)")
      for _, f in ipairs(pbm.MEDIA_FIELDS) do
        if f == "genres" then T.deep_eq(pb.media.genres, doc.media.genres, "genres")
        elseif f == "artwork_url" then T.eq(pb.media.artwork_url, doc.media.artwork_url, "artwork_url")
        else T.eq(pb.media[f], doc.media[f], "media." .. f) end
      end
      T.ok(pbm.KINDS[pb.media.kind] and pbm.STATES[pb.playback.state])
    end)
  end
  it("volume scale is 0..100 on both sides (NUMBER variable keeps the bridge value)", function()
    local _, pb = poll(docs.music)
    T.eq(pb.playback.volume, 37.5)
    local d = json.decode(json.encode(docs.music)); d.playback.volume = 150
    local _, pb2 = poll(d)
    T.is_nil(pb2.playback.volume, "out of range dropped, never rescaled")
  end)
  it("credentials never survive in published URLs (older bridges put ?token= on artwork)", function()
    local d = json.decode(json.encode(docs.movie))
    d.media.artwork_url = "http://192.168.1.10:8765/v1/devices/AA%3ABB/artwork?v=0123&token=s3cret"
    d.source.app_icon_url = "http://192.168.1.10:8765/icon.png?token=s3cret"
    local _, pb = poll(d)
    T.eq(pb.media.artwork_url, "http://192.168.1.10:8765/v1/devices/AA%3ABB/artwork?v=0123")
    T.eq(pb.source.app_icon_url, "http://192.168.1.10:8765/icon.png")
    T.eq(Bridge.strip_secrets("http://h/a?token=x&v=1&API_KEY=y#f"), "http://h/a?v=1#f")
    T.eq(Bridge.strip_secrets("http://h/a?v=1"), "http://h/a?v=1")
  end)
  it("c4.config builds /v1/devices/<id>/now-playing with the id URL-encoded and the token as a header", function()
    local cfg = Config.build({ ["Apple TV Bridge URL"] = "192.168.1.10:8765/", ["Apple TV Device"] = "AA:BB:CC Den",
      ["Apple TV Bridge Token"] = " s3cret ", ["Use Control4 Room Media"] = "Off" }, {})
    local pc = cfg.providers[1]
    T.eq(pc.type, "bridge"); T.eq(pc.provider_name, "appletv")
    T.eq(pc.url, "http://192.168.1.10:8765/v1/devices/AA%3ABB%3ACC%20Den/now-playing")
    T.eq(pc.headers.Authorization, "Bearer s3cret")
    T.no(pc.url:find("s3cret", 1, true))
    local _, pb, fd = poll(docs.movie, pc)
    T.eq(fd.requests[1].headers.Authorization, "Bearer s3cret")
    T.eq(pb.source.provider, "appletv")
  end)
end)
